import itertools

def solve_all_interval(n=9):
    numbers = list(range(n))

    def backtrack(seq, used_nums, used_diffs):
        if len(seq) == n:
            return seq

        for next_num in numbers:
            if next_num in used_nums:
                continue
            if len(seq) > 0:
                diff = abs(seq[-1] - next_num)
                if diff in used_diffs:
                    continue

            used_nums.add(next_num)
            if len(seq) > 0:
                used_diffs.add(diff)

            result = backtrack(seq + [next_num], used_nums, used_diffs)
            if result:
                return result

            used_nums.remove(next_num)
            if len(seq) > 0:
                used_diffs.remove(diff)

        return None

    return backtrack([], set(), set())

solution = solve_all_interval(9)
print(solution)
if solution:
    diffs = [abs(solution[i+1] - solution[i]) for i in range(len(solution)-1)]
    print("Diffs:", diffs)
    print("Sorted diffs:", sorted(diffs))
